CREATE POLICY "chat_messages_select" ON public."chat_messages" AS PERMISSIVE FOR SELECT TO "authenticated"
  USING (
CASE wassell_chat_scope_class()
    WHEN 'all'::text THEN true
    WHEN 'none'::text THEN false
