  USING (((model_id IN ( SELECT models.id
   FROM models
  WHERE (models.name = 'site_settings'::text))) OR ((model_id IN ( SELECT models.id
   FROM models
  WHERE (models.name = 'all_projects'::text))) AND (COALESCE(((data ->> 'is_public'::text))::boolean, false) = true)) OR ((model_id IN ( SELECT models.id
   FROM models
  WHERE (models.name = 'project_details'::text))) AND wassell_project_is_public((data ->> 'project_id'::text))) OR ((model_id IN ( SELECT wassell_public_lookup_model_ids.wassell_public_lookup_model_ids
   FROM wassell_public_lookup_model_ids() wassell_public_lookup_model_ids(wassell_public_lookup_model_ids))) AND wassell_is_public_lookup_target(id, model_id))));
