DROP POLICY IF EXISTS "whatsapp_ai_replies_select" ON public."whatsapp_ai_replies";
CREATE POLICY "whatsapp_ai_replies_select" ON public."whatsapp_ai_replies" AS PERMISSIVE FOR SELECT TO "authenticated"
  USING (
CASE wassell_chat_scope_class()
    WHEN 'all'::text THEN true
    WHEN 'none'::text THEN false
    ELSE (EXISTS ( SELECT 1
       FROM (records r
         JOIN models m ON (((m.id = r.model_id) AND (m.name = 'chats'::text))))
      WHERE ((r.data ->> 'wid'::text) = whatsapp_ai_replies.chat_wid)))
END);
DROP POLICY IF EXISTS "whatsapp_ai_sessions_select" ON public."whatsapp_ai_sessions";
CREATE POLICY "whatsapp_ai_sessions_select" ON public."whatsapp_ai_sessions" AS PERMISSIVE FOR SELECT TO "authenticated"
  USING (
CASE wassell_chat_scope_class()
    WHEN 'all'::text THEN true
    WHEN 'none'::text THEN false
    ELSE (EXISTS ( SELECT 1
       FROM (records r
         JOIN models m ON (((m.id = r.model_id) AND (m.name = 'chats'::text))))
      WHERE ((r.data ->> 'wid'::text) = whatsapp_ai_sessions.chat_wid)))
END);
